local StarChartMaker = {}
local PRODUCTS = {
    constellation_chart = { name = "Karta ozvezdij", parchmentCost = 1, inkCost = 1, time = 3, cost = 40, accuracy = 50, prestige = 3, description = "Karta ozvezdij za navigacijo." },
    lunar_chart = { name = "Lunarna karta", parchmentCost = 1, inkCost = 1, silverCost = 1, time = 5, cost = 100, accuracy = 65, prestige = 6, happiness = 1, description = "Lunarna karta za napovedovanje plim." },
    planetary_ephemeris = { name = "Planetni efemeride", parchmentCost = 2, inkCost = 1, silverCost = 1, time = 8, cost = 240, accuracy = 78, prestige = 10, happiness = 2, description = "Planetni efemeride za astrologijo." },
    silver_etched_chart = { name = "Srebrno vgravirana karta", parchmentCost = 2, inkCost = 1, silverCost = 1, goldCost = 1, time = 11, cost = 560, accuracy = 88, prestige = 17, happiness = 3, description = "Srebrno vgravirana zvezdna karta za plemiče." },
    silver_armillary_chart = { name = "Srebrno armilarna karta", parchmentCost = 3, inkCost = 1, silverCost = 1, goldCost = 1, time = 14, cost = 1100, accuracy = 94, prestige = 25, happiness = 5, description = "Armilarna karta v srebru za visoke plemiče." },
    royal_grand_celestial = { name = "Kraljevski veliki nebesni atlas", parchmentCost = 5, inkCost = 2, goldCost = 2, silverCost = 1, jewelCost = 1, time = 20, cost = 2500, accuracy = 100, prestige = 58, happiness = 12, description = "Veliki kraljevski nebesni atlas z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Astronomska postaja", cost = { gold = 320, wood = 130, stone = 250 }, upkeep = 8, qualityBonus = 5 },
    observatory = { name = "Observatorij", cost = { gold = 1200, wood = 300, stone = 600, brass = 8 }, upkeep = 30, qualityBonus = 18 },
    charting_room = { name = "Kartirnica", cost = { gold = 2800, wood = 400, stone = 800, silver = 40, ink = 8 }, upkeep = 70, qualityBonus = 30 },
    royal_astronomy_atelier = { name = "Kraljevski atelje astronomije", cost = { gold = 11000, wood = 600, stone = 1200, gold = 80, jewel = 25 }, upkeep = 220, qualityBonus = 55, prestigeBonus = 50 },
}
StarChartMaker.parchmentStock = 18; StarChartMaker.inkStock = 14; StarChartMaker.silverStock = 8; StarChartMaker.goldStock = 6; StarChartMaker.jewelStock = 6
StarChartMaker.productStock = {}; StarChartMaker.buildings = {}; StarChartMaker.maker = nil; StarChartMaker.activeMaking = {}; StarChartMaker.totalProducts = 0; StarChartMaker.dayTimer = 0
function StarChartMaker.init() StarChartMaker.parchmentStock=18; StarChartMaker.inkStock=14; StarChartMaker.silverStock=8; StarChartMaker.goldStock=6; StarChartMaker.jewelStock=6; StarChartMaker.productStock={}; StarChartMaker.buildings={}; StarChartMaker.maker=nil; StarChartMaker.activeMaking={}; StarChartMaker.totalProducts=0; StarChartMaker.dayTimer=0; print("[StarChartMaker] Royal Star Chart Maker System initialized (6 products, 4 buildings)") end
function StarChartMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; StarChartMaker.maker={name=n or ("Astronom "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Astronom najet: %s (spretnost: %d)",StarChartMaker.maker.name,s),"success") end; return true end
function StarChartMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function StarChartMaker.build(id) local ok,e=StarChartMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(StarChartMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function StarChartMaker.getQualityBonus() local b=0; for _,bd in ipairs(StarChartMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function StarChartMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.parchmentCost and StarChartMaker.parchmentStock<(d.parchmentCost or 0) then return false,"Premalo pergamenta" end; if d.inkCost and StarChartMaker.inkStock<(d.inkCost or 0) then return false,"Premalo črnila" end; if d.silverCost and StarChartMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and StarChartMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and StarChartMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #StarChartMaker.buildings==0 then return false,"Potrebna delavnica" end; if not StarChartMaker.maker then return false,"Potreben astronom" end; return true end
function StarChartMaker.make(pt,qty) qty=qty or 1; local ok,e=StarChartMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.parchmentCost then StarChartMaker.parchmentStock=StarChartMaker.parchmentStock-d.parchmentCost*qty end; if d.inkCost then StarChartMaker.inkStock=StarChartMaker.inkStock-d.inkCost*qty end; if d.silverCost then StarChartMaker.silverStock=StarChartMaker.silverStock-d.silverCost*qty end; if d.goldCost then StarChartMaker.goldStock=StarChartMaker.goldStock-d.goldCost*qty end; if d.jewelCost then StarChartMaker.jewelStock=StarChartMaker.jewelStock-d.jewelCost*qty end; local t=d.time; if StarChartMaker.maker then t=math.max(1,t-math.floor(StarChartMaker.maker.skill/12)) end; table.insert(StarChartMaker.activeMaking,{id="starchart_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,accuracy=d.accuracy or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function StarChartMaker.completeMaking(m) local q=1.0+(StarChartMaker.getQualityBonus()/100); if StarChartMaker.maker then q=q+(StarChartMaker.maker.skill/150) end; q=math.min(2.5,q); StarChartMaker.productStock[m.productType]=(StarChartMaker.productStock[m.productType] or 0)+m.quantity; StarChartMaker.totalProducts=StarChartMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if StarChartMaker.maker then StarChartMaker.maker.itemsMade=StarChartMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then StarChartMaker.maker.skill=math.min(100,StarChartMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zvezdna karta izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"starchart.completed",{productName=m.productName,accuracy=m.accuracy,prestige=m.prestige,happiness=m.happiness}) end end
function StarChartMaker.update(dt) if not _G.state then return end; StarChartMaker.dayTimer=StarChartMaker.dayTimer+dt; if StarChartMaker.dayTimer>=30 then StarChartMaker.dayTimer=0; for i=#StarChartMaker.activeMaking,1,-1 do local m=StarChartMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then StarChartMaker.completeMaking(m); table.remove(StarChartMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(StarChartMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if StarChartMaker.maker then tu=tu+18 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function StarChartMaker.getStats() return {parchmentStock=StarChartMaker.parchmentStock,inkStock=StarChartMaker.inkStock,silverStock=StarChartMaker.silverStock,goldStock=StarChartMaker.goldStock,jewelStock=StarChartMaker.jewelStock,productStock=StarChartMaker.productStock,numBuildings=#StarChartMaker.buildings,hasMaker=StarChartMaker.maker~=nil,makerName=StarChartMaker.maker and StarChartMaker.maker.name or "—",makerSkill=StarChartMaker.maker and StarChartMaker.maker.skill or 0,activeMaking=#StarChartMaker.activeMaking,totalProducts=StarChartMaker.totalProducts} end
return StarChartMaker
